// fifo_breadboard.sv
//
// A pin-accurate model of the two FIFO exercises of the Logic Synthesis School Kit,
// as they are wired in the build guide (fifo_build.html):
//
//   bb8_fifo_demo   stage 1, exercise BB8: 4013 #1 and FIFO A on the bottom board,
//                   with the temporary wire from pin 12 of 4013 #1 to SO of A
//   p3_fifo_adder   stage 2, exercise P3: three 40105 FIFOs, a 4008 adder, a 4082
//                   4-input AND and two 4013s on two breadboards
//
// The board-level modules are generated by tools/fifo_sv.py from the breadboard
// wires, so every port connection below is a breadboard column that a wire really
// plugs into, and the comment after it gives the numbers of those wires in the
// wiring checklist of the guide.  Do not edit them by hand: change tools/fifo.py
// and run python3 tools/generate.py.
//
// The chips are behavioural models with propagation delays, written from the TI and
// Motorola datasheets, so races and glitches show up as they would on the boards.
// Their ports are named after the pins: p3_si is pin 3, SI.  Power pins are ports
// too, and a chip without VDD and GND drives X.  A floating input, a setup or hold
// violation and data changing right after a FIFO load are reported as errors.
//
// tb_fifo_breadboard replays the tests of the build guide with contact bounce on
// every button, in typical, fast and slow timing corners:
//
//   iverilog -g2012 -o fifo_tb fifo_breadboard.sv && vvp fifo_tb
//
// The 555 module runs at 2 Hz as in the guide.  Each corner covers about 100 s of
// button pressing; the run takes under a second.  This is a simulation model (it
// uses delays and wait), not synthesizable RTL; it is tested with Icarus Verilog 12.

`timescale 1ns / 1ps

// Every rule a chip model checks (floating inputs, setup and hold times)
// counts here, and the testbench fails when the count is not zero.

package lssk_rules;
    int violations = 0;
endpackage

//----------------------------------------------------------------------------
// CMOS inputs must not float: on the board a floating input picks up noise.
// One instance per input pin; the instance name says which pin.
//----------------------------------------------------------------------------

module cmos_input_check (input x);

    import lssk_rules::*;

    initial
        # 1 if (x === 1'bz)
        begin
            $error ("%m: input floats, it needs a wire");
            violations = violations + 1;
        end

    always @ (x)
        if (x === 1'bz)
        begin
            $error ("%m: input floats, it needs a wire");
            violations = violations + 1;
        end

endmodule

//----------------------------------------------------------------------------
// CD74HC40105: 4-bit x 16-word FIFO (TI SCHS222C; CD40105B: SCHS096)
//
// * A rising edge on SI loads D0-D3 while DIR is high.  SI must go low before
//   the next word is accepted.  If SI rises while the FIFO is full, the word is
//   entered as soon as a location frees and SI is still high.
// * DIR goes low after a load until the word has moved on to location 2.
// * The word ripples to location 16; then DOR goes high and Q0-Q3 show it.
// * A falling edge on SO drops the word at the output while DOR is high; DOR
//   goes low while the next word moves up.  Commands to an empty FIFO are
//   ignored.
// * MR clears the control markers: DIR high, DOR low.  The data stay.
// * OE (three-state control) high turns Q0-Q3 off.
//----------------------------------------------------------------------------

module cd74hc40105
# (
    parameter t_flag = 40,  // SI to DIR, SO to DOR and Q, ns
              t_step = 25,  // ripple-through, per location
              t_hold = 25   // data hold time after SI
)
(
    input  p1_oe,
    output p2_dir,
    input  p3_si,
    input  p4_d0,
    input  p5_d1,
    input  p6_d2,
    input  p7_d3,
    input  p8_gnd,
    input  p9_mr,
    output p10_q3,
    output p11_q2,
    output p12_q1,
    output p13_q0,
    output p14_dor,
    input  p15_so,
    input  p16_vcc
);

    import lssk_rules::*;

    wire       powered = p16_vcc === 1'b1 && p8_gnd === 1'b0;
    wire [3:0] d       = { p7_d3, p6_d2, p5_d1, p4_d0 };

    cmos_input_check pin1 (p1_oe), pin3 (p3_si), pin4 (p4_d0), pin5 (p5_d1), pin6 (p6_d2), pin7 (p7_d3), pin9 (p9_mr), pin15 (p15_so);

    logic [16:1] valid     = '0;  // control markers: location k holds a word
    logic [ 3:0] word [1:16];
    logic [ 3:0] head      = '0;  // the latches of location 16
    logic        armed_in  = 1'b1;
    logic        armed_out = 1'b0;
    time         t_load    = 0;
    int          n_words;         // for the testbench

    logic        dir_r, dor_r;
    logic [3:0]  q_r;

    task automatic try_load ();
        if (p9_mr === 1'b0 && p3_si === 1'b1 && armed_in && ! valid [1])
        begin
            word  [1] = d;
            valid [1] = 1'b1;
            armed_in  = 1'b0;
            t_load    = $time;
        end
    endtask

    task automatic try_unload ();
        if (p9_mr === 1'b0 && p15_so === 1'b0 && armed_out)
        begin
            armed_out  = 1'b0;
            valid [16] = 1'b0;  // nothing happens if location 16 is empty
        end
    endtask

    always @ (p3_si)
        if (p3_si === 1'b0)
            armed_in = 1'b1;
        else
            try_load ();

    always @ (p15_so)
        if (p15_so === 1'b1)
            armed_out = 1'b1;
        else
            try_unload ();

    always @ (p9_mr)
        if (p9_mr === 1'b1)
        begin
            valid     = '0;
            armed_in  = 1'b1;
            armed_out = p15_so === 1'b1;
        end
        else
            try_load ();

    // Ripple-through: every word moves one location per step while the next
    // location is empty.  The moves of one step happen together.

    wire movable = | (valid [15:1] & ~ valid [16:2]);

    always
    begin
        wait (movable && p9_mr === 1'b0);
        # t_step;
        begin : step
            logic [16:1] v;
            v = valid;
            for (int k = 15; k >= 1; k --)
                if (v [k] && ! v [k + 1])
                begin
                    word  [k + 1] = word [k];
                    valid [k + 1] = 1'b1;
                    valid [k]     = 1'b0;
                end
            if (valid [16] && ! v [16])
                head = word [16];
        end
        try_load ();  // a word waiting on a full FIFO goes in now
    end

    always @ (d)
        if (t_load != 0 && $time - t_load < t_hold)
        begin
            $error ("%m: D changed %0t ns after the load", $time - t_load);
            violations = violations + 1;
        end

    always
    begin
        n_words = 0;
        for (int k = 1; k <= 16; k ++)
            n_words += valid [k];
        @ (valid);
    end

    // Outputs, with transport delay

    always
    begin
        dir_r <= # t_flag p9_mr === 1'b1 || ! valid [1];
        @ (valid [1] or p9_mr);
    end

    always
    begin
        dor_r <= # t_flag p9_mr === 1'b0 && valid [16];
        @ (valid [16] or p9_mr);
    end

    always
    begin
        q_r <= # t_flag head;
        @ (head);
    end

    assign p2_dir  = powered ? dir_r : 1'bx;
    assign p14_dor = powered ? dor_r : 1'bx;

    assign { p10_q3, p11_q2, p12_q1, p13_q0 } =
          ! powered       ? 4'bx
        : p1_oe === 1'b1  ? 4'bz
        : p1_oe === 1'b0  ? q_r
        :                   4'bx;

endmodule

//----------------------------------------------------------------------------
// CD4013B: dual D flip-flop, rising edge, asynchronous active-high R and S
// (TI SCHS023).  Setup and hold violations are reported as errors.
//----------------------------------------------------------------------------

module cd4013b_flip_flop
# (
    parameter t_pd    = 150,
              t_setup = 40,
              t_hold  = 5
)
(
    input        clk,
    input        d,
    input        r,
    input        s,
    output logic q,
    output logic q_n
);

    import lssk_rules::*;

    logic state  = 1'b0;
    time  t_d    = 0;
    time  t_edge = 0;

    always @ (posedge clk or posedge r or posedge s)
        if (r === 1'b1)
            state <= 1'b0;
        else if (s === 1'b1)
            state <= 1'b1;
        else
        begin
            if (t_d != 0 && $time - t_d < t_setup)
            begin
                $error ("%m: D changed %0t ns before the clock edge", $time - t_d);
                violations = violations + 1;
            end
            state  <= d;
            t_edge  = $time;
        end

    always @ (d)
    begin
        if (t_edge != 0 && $time - t_edge < t_hold)
        begin
            $error ("%m: D changed %0t ns after the clock edge", $time - t_edge);
            violations = violations + 1;
        end
        t_d = $time;
    end

    always
    begin
        q   <= # t_pd   state;
        q_n <= # t_pd ~ state;
        @ (state);
    end

endmodule

module cd4013b
# (
    parameter t_pd = 150
)
(
    output p1_q1,
    output p2_q1_n,
    input  p3_clk1,
    input  p4_r1,
    input  p5_d1,
    input  p6_s1,
    input  p7_vss,
    input  p8_s2,
    input  p9_d2,
    input  p10_r2,
    input  p11_clk2,
    output p12_q2_n,
    output p13_q2,
    input  p14_vdd
);

    wire powered = p14_vdd === 1'b1 && p7_vss === 1'b0;
    wire q1, q1_n, q2, q2_n;

    cmos_input_check pin3 (p3_clk1), pin4 (p4_r1), pin5 (p5_d1), pin6 (p6_s1), pin8 (p8_s2), pin9 (p9_d2), pin10 (p10_r2), pin11 (p11_clk2);

    cd4013b_flip_flop # (.t_pd (t_pd)) ff1
        (.clk (p3_clk1), .d (p5_d1), .r (p4_r1), .s (p6_s1), .q (q1), .q_n (q1_n));

    cd4013b_flip_flop # (.t_pd (t_pd)) ff2
        (.clk (p11_clk2), .d (p9_d2), .r (p10_r2), .s (p8_s2), .q (q2), .q_n (q2_n));

    assign p1_q1    = powered ? q1   : 1'bx;
    assign p2_q1_n  = powered ? q1_n : 1'bx;
    assign p13_q2   = powered ? q2   : 1'bx;
    assign p12_q2_n = powered ? q2_n : 1'bx;

endmodule

//----------------------------------------------------------------------------
// CD4008B: 4-bit full adder with fast carry (pinout of the pin-for-pin
// equivalent Motorola MC14008B)
//----------------------------------------------------------------------------

module cd4008b
# (
    parameter t_pd = 400
)
(
    input  p1_a4,
    input  p2_b3,
    input  p3_a3,
    input  p4_b2,
    input  p5_a2,
    input  p6_b1,
    input  p7_a1,
    input  p8_vss,
    input  p9_cin,
    output p10_s1,
    output p11_s2,
    output p12_s3,
    output p13_s4,
    output p14_cout,
    input  p15_b4,
    input  p16_vdd
);

    wire       powered = p16_vdd === 1'b1 && p8_vss === 1'b0;

    cmos_input_check pin1 (p1_a4), pin2 (p2_b3), pin3 (p3_a3), pin4 (p4_b2), pin5 (p5_a2), pin6 (p6_b1), pin7 (p7_a1), pin9 (p9_cin), pin15 (p15_b4);
    wire [3:0] a = { p1_a4,  p3_a3, p5_a2, p7_a1 };
    wire [3:0] b = { p15_b4, p2_b3, p4_b2, p6_b1 };

    logic [4:0] r;

    always
    begin
        r <= # t_pd powered ? { 1'b0, a } + { 1'b0, b } + p9_cin : 5'bx;
        @ (a or b or p9_cin or powered);
    end

    assign { p14_cout, p13_s4, p12_s3, p11_s2, p10_s1 } = r;

endmodule

//----------------------------------------------------------------------------
// CD4082B: dual 4-input AND gate (TI SCHS057).  Pins 6 and 8 are not
// connected inside the chip.
//----------------------------------------------------------------------------

module cd4082b
# (
    parameter t_pd = 125
)
(
    output p1_j,
    input  p2_a,
    input  p3_b,
    input  p4_c,
    input  p5_d,
    input  p7_vss,
    input  p9_e,
    input  p10_f,
    input  p11_g,
    input  p12_h,
    output p13_k,
    input  p14_vdd
);

    wire  powered = p14_vdd === 1'b1 && p7_vss === 1'b0;

    cmos_input_check pin2 (p2_a), pin3 (p3_b), pin4 (p4_c), pin5 (p5_d), pin9 (p9_e), pin10 (p10_f), pin11 (p11_g), pin12 (p12_h);
    logic j, k;

    always
    begin
        j <= # t_pd powered ? p2_a & p3_b & p4_c & p5_d     : 1'bx;
        k <= # t_pd powered ? p9_e & p10_f & p11_g & p12_h  : 1'bx;
        @ (p2_a or p3_b or p4_c or p5_d or p9_e or p10_f or p11_g or p12_h or powered);
    end

    assign p1_j  = j;
    assign p13_k = k;

endmodule

//----------------------------------------------------------------------------
// bb8_fifo_demo: Stage 1 of the build guide, exercise BB8.
// Generated from the breadboard wires by tools/fifo_sv.py.
//----------------------------------------------------------------------------
module bb8_fifo_demo
(
    // OUT pins of the button and clock modules
    input        clk,      // clock 555 module, OUT in 6j
    input        rst,      // reset module, OUT in 7j
    input        pushA,    // push A module, OUT in 8j
    input        popC,     // pop C module, OUT in 1j
    input        d0,       // data d0 module, OUT in 27j
    input        d1,       // data d1 module, OUT in 28j
    input        d2,       // data d2 module, OUT in 29j

    // LEDs
    output [4:1] led_ab
);

    supply1 vdd;
    supply0 gnd;

    wire sA;    // push A in step with the clock: SI of A
    wire pC;    // pop button in step with the clock, inverted: SO of A through the temporary wire
    wire a0;    // head of A, bit 0
    wire a1;    // head of A, bit 1
    wire a2;    // head of A, bit 2
    wire rA;    // A has data: DOR of A

    // 4013 #1, bottom board, columns 4-10, pin 1 in 4f

    cd4013b u_u1
    (
        .p1_q1    ( sA    ),  // wire 19
        .p2_q1_n  (       ),  // not used
        .p3_clk1  ( clk   ),  // wires 20, 28
        .p4_r1    ( rst   ),  // wires 21, 30
        .p5_d1    ( pushA ),  // wire 31
        .p6_s1    ( gnd   ),  // wire 9
        .p7_vss   ( gnd   ),  // wire 6
        .p8_s2    ( gnd   ),  // wire 10
        .p9_d2    ( popC  ),  // wire 18
        .p10_r2   ( rst   ),  // wires 21, 22
        .p11_clk2 ( clk   ),  // wire 20
        .p12_q2_n ( pC    ),  // wire 23
        .p13_q2   (       ),  // not used
        .p14_vdd  ( vdd   )   // wire 5
    );

    // 40105 A, bottom board, columns 24-31, pin 1 in 24f

    cd74hc40105 u_a
    (
        .p1_oe   ( gnd ),  // wire 11
        .p2_dir  (     ),  // not used
        .p3_si   ( sA  ),  // wire 19
        .p4_d0   ( d0  ),  // wire 38
        .p5_d1   ( d1  ),  // wire 40
        .p6_d2   ( d2  ),  // wire 41
        .p7_d3   ( gnd ),  // wire 12
        .p8_gnd  ( gnd ),  // wire 8
        .p9_mr   ( rst ),  // wire 22
        .p10_q3  (     ),  // not used
        .p11_q2  ( a2  ),  // wire 15
        .p12_q1  ( a1  ),  // wire 16
        .p13_q0  ( a0  ),  // wire 17
        .p14_dor ( rA  ),  // wire 14
        .p15_so  ( pC  ),  // wire 23
        .p16_vcc ( vdd )   // wire 7
    );

    // LEDs: each one shows the column its leg or header pin is in

    assign led_ab [1]      = rA;    // A/B LED module, LED 1
    assign led_ab [2]      = a2;    // A/B LED module, LED 2
    assign led_ab [3]      = a1;    // A/B LED module, LED 3
    assign led_ab [4]      = a0;    // A/B LED module, LED 4

endmodule

//----------------------------------------------------------------------------
// p3_fifo_adder: Stage 2 of the build guide, exercise P3.
// Generated from the breadboard wires by tools/fifo_sv.py.
//----------------------------------------------------------------------------
module p3_fifo_adder
# (
    parameter t_gate = 125,  // 4082
              t_ff   = 150,  // 4013
              t_add  = 400   // 4008
)
(
    // OUT pins of the button and clock modules
    input        clk,      // clock 555 module, OUT in 6j
    input        rst,      // reset module, OUT in 7j
    input        pushA,    // push A module, OUT in 8j
    input        pushB,    // push B module, OUT in 17j
    input        popC,     // pop C module, OUT in 1j
    input        d0,       // data d0 module, OUT in 27j
    input        d1,       // data d1 module, OUT in 28j
    input        d2,       // data d2 module, OUT in 29j

    // LEDs
    output [8:1] led_ab,
    output [8:1] led_c,
    output       led_yellow
);

    supply1 vdd;
    supply0 gnd;

    wire sA;    // push A in step with the clock: SI of A
    wire sB;    // push B in step with the clock: SI of B
    wire pC;    // pop C in step with the clock, inverted: SO of C
    wire a0;    // head of A, bit 0
    wire a1;    // head of A, bit 1
    wire a2;    // head of A, bit 2
    wire b0;    // head of B, bit 0
    wire b1;    // head of B, bit 1
    wire b2;    // head of B, bit 2
    wire s0;    // sum, bit 0
    wire s1;    // sum, bit 1
    wire s2;    // sum, bit 2
    wire s3;    // sum, bit 3
    wire c0;    // head of C, bit 0
    wire c1;    // head of C, bit 1
    wire c2;    // head of C, bit 2
    wire c3;    // head of C, bit 3
    wire rA;    // A has data: DOR of A
    wire rB;    // B has data: DOR of B
    wire fC;    // C has room: DIR of C
    wire vC;    // C has data: DOR of C
    wire t;     // transfer
    wire tb;    // NOT transfer
    wire go;    // transfer at the next clock edge

    // 4013 #1, bottom board, columns 4-10, pin 1 in 4f

    cd4013b # (.t_pd (t_ff)) u_u1
    (
        .p1_q1    ( sA    ),  // wire 19
        .p2_q1_n  (       ),  // not used
        .p3_clk1  ( clk   ),  // wires 20, 28, 91
        .p4_r1    ( rst   ),  // wires 21, 30, 92
        .p5_d1    ( pushA ),  // wire 31
        .p6_s1    ( gnd   ),  // wire 9
        .p7_vss   ( gnd   ),  // wire 6
        .p8_s2    ( gnd   ),  // wire 10
        .p9_d2    ( popC  ),  // wire 18
        .p10_r2   ( rst   ),  // wires 21, 22, 76
        .p11_clk2 ( clk   ),  // wire 20
        .p12_q2_n ( pC    ),  // wire 69
        .p13_q2   (       ),  // not used
        .p14_vdd  ( vdd   )   // wire 5
    );

    // 4013 #2, bottom board, columns 13-19, pin 1 in 13f

    cd4013b # (.t_pd (t_ff)) u_u2
    (
        .p1_q1    ( sB    ),  // wire 93
        .p2_q1_n  (       ),  // not used
        .p3_clk1  ( clk   ),  // wires 91, 95
        .p4_r1    ( rst   ),  // wires 92, 96, 97
        .p5_d1    ( pushB ),  // wire 103
        .p6_s1    ( gnd   ),  // wire 63
        .p7_vss   ( gnd   ),  // wire 52
        .p8_s2    ( gnd   ),  // wire 64
        .p9_d2    ( go    ),  // wire 77
        .p10_r2   ( rst   ),  // wire 96
        .p11_clk2 ( clk   ),  // wire 95
        .p12_q2_n ( tb    ),  // wire 78
        .p13_q2   ( t     ),  // wires 71, 94
        .p14_vdd  ( vdd   )   // wire 51
    );

    // 40105 A, bottom board, columns 24-31, pin 1 in 24f

    cd74hc40105 u_a
    (
        .p1_oe   ( gnd ),  // wire 11
        .p2_dir  (     ),  // not used
        .p3_si   ( sA  ),  // wire 19
        .p4_d0   ( d0  ),  // wires 38, 99
        .p5_d1   ( d1  ),  // wires 40, 100
        .p6_d2   ( d2  ),  // wires 41, 101
        .p7_d3   ( gnd ),  // wire 12
        .p8_gnd  ( gnd ),  // wire 8
        .p9_mr   ( rst ),  // wire 22
        .p10_q3  (     ),  // not used
        .p11_q2  ( a2  ),  // wires 15, 82
        .p12_q1  ( a1  ),  // wires 16, 84
        .p13_q0  ( a0  ),  // wire 17
        .p14_dor ( rA  ),  // wires 14, 80
        .p15_so  ( t   ),  // wires 94, 98
        .p16_vcc ( vdd )   // wire 7
    );

    // 40105 B, bottom board, columns 36-43, pin 1 in 36f

    cd74hc40105 u_b
    (
        .p1_oe   ( gnd ),  // wire 65
        .p2_dir  (     ),  // not used
        .p3_si   ( sB  ),  // wire 93
        .p4_d0   ( d0  ),  // wire 99
        .p5_d1   ( d1  ),  // wire 100
        .p6_d2   ( d2  ),  // wire 101
        .p7_d3   ( gnd ),  // wire 66
        .p8_gnd  ( gnd ),  // wire 54
        .p9_mr   ( rst ),  // wire 97
        .p10_q3  (     ),  // not used
        .p11_q2  ( b2  ),  // wire 88
        .p12_q1  ( b1  ),  // wires 83, 89
        .p13_q0  ( b0  ),  // wires 85, 90
        .p14_dor ( rB  ),  // wires 79, 87
        .p15_so  ( t   ),  // wire 98
        .p16_vcc ( vdd )   // wire 53
    );

    // 40105 C, top board, columns 10-17, pin 1 in 10f

    cd74hc40105 u_c
    (
        .p1_oe   ( gnd ),  // wire 55
        .p2_dir  ( fC  ),  // wires 68, 70
        .p3_si   ( t   ),  // wire 71
        .p4_d0   ( s0  ),  // wire 72
        .p5_d1   ( s1  ),  // wire 73
        .p6_d2   ( s2  ),  // wire 74
        .p7_d3   ( s3  ),  // wire 75
        .p8_gnd  ( gnd ),  // wire 46
        .p9_mr   ( rst ),  // wire 76; LED 8 of the LED module on C
        .p10_q3  ( c3  ),  // LED 7 of the LED module on C
        .p11_q2  ( c2  ),  // LED 6 of the LED module on C
        .p12_q1  ( c1  ),  // LED 5 of the LED module on C
        .p13_q0  ( c0  ),  // LED 4 of the LED module on C
        .p14_dor ( vC  ),  // LED 3 of the LED module on C
        .p15_so  ( pC  ),  // wire 69; LED 2 of the LED module on C
        .p16_vcc ( vdd )   // wire 45; LED 1 of the LED module on C
    );

    // 4082, top board, columns 21-27, pin 1 in 21f

    cd4082b # (.t_pd (t_gate)) u_and
    (
        .p1_j    ( go  ),  // wire 77
        .p2_a    ( tb  ),  // wire 78
        .p3_b    ( fC  ),  // wire 70
        .p4_c    ( rB  ),  // wire 79
        .p5_d    ( rA  ),  // wire 80
        .p7_vss  ( gnd ),  // wire 48
        .p9_e    ( gnd ),  // wire 59
        .p10_f   ( gnd ),  // wire 58
        .p11_g   ( gnd ),  // wire 57
        .p12_h   ( gnd ),  // wire 56
        .p13_k   (     ),  // not used
        .p14_vdd ( vdd )   // wire 47
    );

    // 4008, top board, columns 30-37, pin 1 in 30f

    cd4008b # (.t_pd (t_add)) u_add
    (
        .p1_a4    ( gnd ),  // wire 60
        .p2_b3    ( b2  ),  // wire 81
        .p3_a3    ( a2  ),  // wire 82
        .p4_b2    ( b1  ),  // wire 83
        .p5_a2    ( a1  ),  // wire 84
        .p6_b1    ( b0  ),  // wire 85
        .p7_a1    ( a0  ),  // wire 86
        .p8_vss   ( gnd ),  // wire 50
        .p9_cin   ( gnd ),  // wire 62
        .p10_s1   ( s0  ),  // wire 72
        .p11_s2   ( s1  ),  // wire 73
        .p12_s3   ( s2  ),  // wire 74
        .p13_s4   ( s3  ),  // wire 75
        .p14_cout (     ),  // not used
        .p15_b4   ( gnd ),  // wire 61
        .p16_vdd  ( vdd )   // wire 49
    );

    // LEDs: each one shows the column its leg or header pin is in

    assign led_ab [1]      = rA;    // A/B LED module, LED 1
    assign led_ab [2]      = a2;    // A/B LED module, LED 2
    assign led_ab [3]      = a1;    // A/B LED module, LED 3
    assign led_ab [4]      = a0;    // A/B LED module, LED 4
    assign led_ab [5]      = rB;    // A/B LED module, LED 5
    assign led_ab [6]      = b2;    // A/B LED module, LED 6
    assign led_ab [7]      = b1;    // A/B LED module, LED 7
    assign led_ab [8]      = b0;    // A/B LED module, LED 8

    assign led_c [1]       = vdd;   // LED module on C, LED 1: pin 16 VCC
    assign led_c [2]       = pC;    // LED module on C, LED 2: pin 15 SO
    assign led_c [3]       = vC;    // LED module on C, LED 3: pin 14 DOR
    assign led_c [4]       = c0;    // LED module on C, LED 4: pin 13 Q0
    assign led_c [5]       = c1;    // LED module on C, LED 5: pin 12 Q1
    assign led_c [6]       = c2;    // LED module on C, LED 6: pin 11 Q2
    assign led_c [7]       = c3;    // LED module on C, LED 7: pin 10 Q3
    assign led_c [8]       = rst;   // LED module on C, LED 8: pin 9 MR

    assign led_yellow      = fC;    // yellow 5V LED, long leg in 11j

endmodule

//----------------------------------------------------------------------------
// Testbench: the tests of the build guide, with contact bounce on every button
//----------------------------------------------------------------------------

// A button module: 5 ms of bounce on every press and release, like a real
// 12 x 12 mm tactile switch, then the level the finger asks for.

module button_with_bounce
# (
    parameter bit bounce = 1
)
(
    input        want,
    output logic out
);

    initial out = 1'b0;

    always @ (want)
        if (bounce)
        begin
            out = want;  # 300_000;
            out = ~ want; # 400_000;
            out = want;  # 800_000;
            out = ~ want; # 1_100_000;
            out = want;
        end
        else
            out = want;

endmodule

module p3_test
# (
    parameter corner = "typical",
              t_gate = 125,
              t_ff   = 150,
              t_add  = 400
)
(
    output logic done,
    output int   errors
);

    localparam time ms = 64'd1_000_000;

    logic clk = 1'b0;
    logic [6:0] want = '0;  // rst, push A, push B, pop C, d0, d1, d2
    wire  [6:0] btn;
    wire  [8:1] led_ab, led_c;
    wire        led_yellow;

    for (genvar i = 0; i < 7; i ++)
    begin : buttons
        button_with_bounce b (.want (want [i]), .out (btn [i]));
    end

    always # (250 * ms) clk = ~ clk;  // the 555 module at 2 Hz

    p3_fifo_adder # (.t_gate (t_gate), .t_ff (t_ff), .t_add (t_add)) dut
    (
        .clk        ( clk        ),
        .rst        ( btn [0]    ),
        .pushA      ( btn [1]    ),
        .pushB      ( btn [2]    ),
        .popC       ( btn [3]    ),
        .d0         ( btn [4]    ),
        .d1         ( btn [5]    ),
        .d2         ( btn [6]    ),
        .led_ab     ( led_ab     ),
        .led_c      ( led_c      ),
        .led_yellow ( led_yellow )
    );

    localparam RST = 0, PUSH_A = 1, PUSH_B = 2, POP_C = 3;

    // What the LEDs show
    wire [3:0] c_head  = { led_c [7], led_c [6], led_c [5], led_c [4] };  // Q3 Q2 Q1 Q0
    wire       c_valid = led_c [3];   // DOR of C
    wire       c_room  = led_yellow;  // DIR of C
    wire       a_valid = led_ab [1];
    wire [2:0] a_head  = { led_ab [2], led_ab [3], led_ab [4] };
    wire       b_valid = led_ab [5];

    int popped [0:63];
    int n_popped = 0;

    task automatic check (input bit ok, input string what);
        if (! ok)
        begin
            $error ("p3 %s corner: %s", corner, what);
            errors ++;
        end
    endtask

    // Hold the data buttons, press and release one button, release the data buttons
    task automatic press (input int b, input logic [2:0] data, input time hold, input time after);
        want [6:4] = data;
        # (150 * ms);
        want [b] = 1'b1;
        # hold;
        want [b] = 1'b0;
        # (150 * ms);
        want [6:4] = '0;
        # after;
    endtask

    task automatic push (input int b, input logic [2:0] data);
        press (b, data, 700 * ms, 600 * ms);
    endtask

    task automatic pop ();
        if (c_valid === 1'b1)
        begin
            popped [n_popped] = c_head;
            n_popped ++;
        end
        press (POP_C, 3'd0, 700 * ms, 600 * ms);
    endtask

    initial
    begin
        done = 1'b0;
        errors = 0;
        # (37_300_000);  // people do not press buttons in step with the clock

        press (RST, 3'd0, 300 * ms, 600 * ms);
        check (c_room === 1'b1 && c_valid === 1'b0 && a_valid === 1'b0, "after reset");

        push (PUSH_A, 3);
        check (a_valid === 1'b1 && a_head === 3'd3, "A shows 3");
        push (PUSH_B, 2);
        # (1500 * ms);
        check (c_valid === 1'b1 && c_head === 4'd5 && a_valid === 1'b0 && b_valid === 1'b0, "3 + 2 = 5 in C");

        push (PUSH_A, 1);
        push (PUSH_A, 4);
        push (PUSH_A, 7);
        # (1500 * ms);
        check (dut.u_c.n_words == 1 && a_valid === 1'b1, "A waits for B");
        push (PUSH_B, 2);
        push (PUSH_B, 3);
        push (PUSH_B, 0);
        # (2000 * ms);
        check (dut.u_c.n_words == 4, "three more sums in C");

        repeat (5)
            pop ();

        for (int k = 0; k < 18; k ++)  // fill C: backpressure
        begin
            press (PUSH_A, k % 8, 700 * ms, 50 * ms);
            press (PUSH_B, 1,     700 * ms, 50 * ms);
        end
        # (3000 * ms);
        check (dut.u_c.n_words == 16 && c_room === 1'b0, "C full, yellow LED off");
        check (dut.u_a.n_words == 2 && dut.u_b.n_words == 2 && a_valid === 1'b1 && b_valid === 1'b1,
               "A and B keep the last two pairs");
        pop ();
        # (2000 * ms);
        check (dut.u_c.n_words == 16 && dut.u_a.n_words == 1, "one pop moves one pair");

        repeat (18)
            pop ();

        begin : compare
            int expected [0:21];
            expected [0] = 5;
            expected [1] = 3;
            expected [2] = 7;
            expected [3] = 7;
            for (int k = 0; k < 18; k ++)
                expected [4 + k] = k % 8 + 1;
            check (n_popped == 22, $sformatf ("%0d sums popped instead of 22", n_popped));
            for (int k = 0; k < 22 && k < n_popped; k ++)
                check (popped [k] == expected [k],
                       $sformatf ("sum %0d is %0d instead of %0d", k, popped [k], expected [k]));
        end

        $display ("p3_fifo_adder, %s corner: %0d sums popped in order, %0d errors, %0d s simulated",
                  corner, n_popped, errors, $time / (1000 * ms));
        done = 1'b1;
    end

endmodule

module bb8_test
(
    output logic done,
    output int   errors
);

    localparam time ms = 64'd1_000_000;

    logic clk = 1'b0;
    logic [6:0] want = '0;  // rst, push A, -, pop C, d0, d1, d2
    wire  [6:0] btn;
    wire  [4:1] led_ab;

    for (genvar i = 0; i < 7; i ++)
    begin : buttons
        button_with_bounce b (.want (want [i]), .out (btn [i]));
    end

    always # (250 * ms) clk = ~ clk;

    bb8_fifo_demo dut
    (
        .clk    ( clk     ),
        .rst    ( btn [0] ),
        .pushA  ( btn [1] ),
        .popC   ( btn [3] ),
        .d0     ( btn [4] ),
        .d1     ( btn [5] ),
        .d2     ( btn [6] ),
        .led_ab ( led_ab  )
    );

    localparam RST = 0, PUSH_A = 1, POP_C = 3;

    task automatic press (input int b, input logic [2:0] data, input time hold);
        want [6:4] = data;
        # (150 * ms);
        want [b] = 1'b1;
        # hold;
        want [b] = 1'b0;
        # (150 * ms);
        want [6:4] = '0;
        # (600 * ms);
    endtask

    int seen [0:7];
    int n;

    initial
    begin
        n = 0;
        done = 1'b0;
        errors = 0;
        # (37_300_000);
        press (RST, 3'd0, 300 * ms);
        if (led_ab [1] !== 1'b0)
            errors ++;
        press (PUSH_A, 3'd2, 700 * ms);
        press (PUSH_A, 3'd5, 700 * ms);
        press (PUSH_A, 3'd7, 2000 * ms);  // held for four ticks: still one word

        while (led_ab [1] === 1'b1 && n < 8)
        begin
            seen [n] = { led_ab [2], led_ab [3], led_ab [4] };
            n ++;
            press (POP_C, 3'd0, 700 * ms);
        end

        if (n != 3 || seen [0] != 2 || seen [1] != 5 || seen [2] != 7)
        begin
            $error ("bb8: popped %0d words: %0d %0d %0d", n, seen [0], seen [1], seen [2]);
            errors ++;
        end

        $display ("bb8_fifo_demo: popped %0d %0d %0d, %0d errors", seen [0], seen [1], seen [2], errors);
        done = 1'b1;
    end

endmodule

module tb_fifo_breadboard;

    import lssk_rules::*;

    wire       done_bb8, done_typ, done_fast, done_slow;
    int        err_bb8,  err_typ,  err_fast,  err_slow;

    bb8_test bb8 (.done (done_bb8), .errors (err_bb8));

    p3_test # (.corner ("typical"), .t_gate (125), .t_ff (150), .t_add (400))
        typical (.done (done_typ), .errors (err_typ));

    p3_test # (.corner ("fast"), .t_gate (60), .t_ff (60), .t_add (150))
        fast (.done (done_fast), .errors (err_fast));

    p3_test # (.corner ("slow"), .t_gate (250), .t_ff (300), .t_add (800))
        slow (.done (done_slow), .errors (err_slow));

    initial
    begin
        wait (done_bb8 && done_typ && done_fast && done_slow);

        if (violations != 0)
            $display ("%0d violations of setup, hold or floating-input rules", violations);

        if (err_bb8 + err_typ + err_fast + err_slow + violations == 0)
            $display ("PASS");
        else
            $display ("FAIL: %0d errors", err_bb8 + err_typ + err_fast + err_slow + violations);

        $finish;
    end

endmodule
